        with redirect_stdout(output):
            self.assertEqual(main(["health"]), 0)
        self.assertEqual(json.loads(output.getvalue()), {
            "service": "forgetting-evidence",
            "status": "ok",
        })


if __name__ == "__main__":
    unittest.main()

